"""Randomised request generator for the cache-group protocol."""
import json, random, sys
sys.path.insert(0, '/workspace/dev')
from ref import Topo

TOPOS = [
    ['leaf-spine', 3, 1], ['leaf-spine', 4, 2], ['leaf-spine', 6, 2], ['leaf-spine', 2, 1],
    ['leaf-spine', 5, 2],
    ['clos', 4, 'tor', 0], ['clos', 4, 'pod', 1], ['clos', 6, 'tor', 1], ['clos', 6, 'pod', 0],
    ['clos', 8, 'tor', 1], ['clos', 8, 'pod', 1], ['clos', 4, 'tor', 1],
    ['torus2d', 3, 'host'], ['torus2d', 4, 'row'], ['torus2d', 5, 'host'], ['torus2d', 4, 'host'],
    ['torus2d', 6, 'host'], ['torus2d', 3, 'row'],
    ['torus3d', 3, 'host'], ['torus3d', 4, 'line'], ['torus3d', 3, 'line'],
    ['dragonfly', 4, 3, 1, 'router'], ['dragonfly', 4, 3, 1, 'group'], ['dragonfly', 4, 3, 1, 'target'],
    ['dragonfly', 3, 2, 1, 'group'], ['dragonfly', 6, 5, 1, 'target'], ['dragonfly', 9, 4, 2, 'group'],
    ['dragonfly-plus', 4, 2, 3, 1, 0, 'tor'], ['dragonfly-plus', 4, 2, 3, 1, 0, 'group'],
    ['dragonfly-plus', 3, 4, 2, 0, 1, 'group'], ['dragonfly-plus', 2, 2, 1, 1, 0, 'tor'],
    ['dragonfly-plus', 5, 3, 2, 1, 0, 'group'], ['dragonfly-plus', 3, 2, 1, 0, 1, 'tor'],
]

class Bad(Exception):
    pass

def build_session(rng, spec, ntasks=None, ngroups=None, ntx=None, maxedits=8,
                  wild=0.45, pins=True, force_bad=None, task_count_zero=False,
                  qsize=5):
    topo = Topo(spec)
    n = topo.n
    tcount = len(topo.foots)
    by_dom = {}
    for tid, dom in enumerate(topo.domains):
        by_dom.setdefault(dom, []).append(tid)
    doms = sorted(by_dom)
    g = rng.randint(1, 10) if ngroups is None else ngroups
    g = max(1, min(g, 8192))
    pool = [(rng.choice(doms), rng.choice([0, 1, 7, 42, 10 ** 9]))
            for _ in range(rng.randint(1, min(5, len(doms))))]
    quota = [rng.randint(1, 8) for _ in range(g)]
    budget = [rng.choice([1, 3, 100, 10 ** 12]) for _ in range(g)]
    gkey = [rng.choice(pool) for _ in range(g)]
    same_key = [[h for h in range(g) if gkey[h] == gkey[x]] for x in range(g)]
    d = 0 if task_count_zero else (ntasks if ntasks is not None else rng.randint(1, 40))
    tasks = []
    for tid in range(d):
        gid = rng.randrange(g)
        dom, cls = gkey[gid]
        tpl = rng.choice(by_dom[dom])
        weight = rng.randint(1, max(1, min(4, quota[gid] * budget[gid])))
        pin = 1 if (pins and rng.random() < 0.3) else 0
        tasks.append([tpl, gid, weight, cls, pin])
    fp = [set() for _ in range(g)]
    load = [0] * g
    for t in tasks:
        fp[t[1]] |= set(topo.foots[t[0]])
        load[t[1]] += t[2]
    for gid in range(g):
        if load[gid] > quota[gid] * budget[gid]:
            budget[gid] = (load[gid] + quota[gid] - 1) // quota[gid]
    caps = [0] * n
    for gid in range(g):
        if fp[gid]:
            for x in fp[gid]:
                caps[x] += quota[gid]
    for x in range(n):
        if rng.random() < 0.45:
            caps[x] += rng.randint(0, 6)

    if force_bad == 'mixed' and d >= 2 and gkey[tasks[1][1]][1] + 5 <= 10 ** 9:
        tasks[1][3] = gkey[tasks[1][1]][1] + 5
    elif force_bad == 'quota0' and d >= 1:
        quota[tasks[0][1]] = 0
    elif force_bad == 'work' and d >= 1:
        idx = max(range(d), key=lambda i: tasks[i][2])
        gid = tasks[idx][1]
        quota[gid], budget[gid] = 1, 1
        tasks[idx][2] = 10 ** 9
    elif force_bad == 'capacity' and d >= 1:
        gid = tasks[0][1]
        if not fp[gid]:
            raise Bad
        caps[min(fp[gid])] = 0
    elif force_bad is not None:
        raise Bad

    def qmake():
        return {'groups': [rng.randrange(g) for _ in range(rng.randint(0, qsize))],
                'nodes': [rng.randrange(n) for _ in range(rng.randint(0, qsize))],
                'tasks': [rng.randrange(d) for _ in range(rng.randint(0, qsize))] if d else []}

    txs = []
    for _ in range(ntx if ntx is not None else rng.randint(0, 12)):
        edits = []
        chaotic = rng.random() < wild
        for _ in range(rng.randint(0, maxedits)):
            if d and rng.random() < 0.62:
                tid = rng.randrange(d)
                kind = rng.choices(['move', 'weight', 'class', 'bind', 'pin'],
                                   weights=[6, 5, 3, 4, 3] if chaotic else [8, 5, 1, 4, 4])[0]
                if kind == 'move':
                    if chaotic and rng.random() < 0.5:
                        target = rng.randrange(g)
                    else:
                        target = rng.choice(same_key[tasks[tid][1]])
                    edits.append(['move', tid, target])
                elif kind == 'weight':
                    edits.append(['weight', tid, rng.randint(1, 10 ** 9) if chaotic else rng.randint(1, 7)])
                elif kind == 'class':
                    edits.append(['class', tid, rng.choice([0, 1, 7, 42, 10 ** 9]) if chaotic
                                  else gkey[tasks[tid][1]][1]])
                elif kind == 'bind':
                    edits.append(['bind', tid, rng.randrange(tcount) if chaotic
                                  else rng.choice(by_dom[gkey[tasks[tid][1]][0]])])
                else:
                    edits.append(['pin', tid, rng.randint(0, 1)])
            else:
                kind = rng.choices(['quota', 'budget', 'cap'], weights=[5, 3, 4] if chaotic else [4, 2, 4])[0]
                if kind == 'quota':
                    edits.append(['quota', rng.randrange(g), rng.randint(0, 64) if chaotic else rng.randint(1, 20)])
                elif kind == 'budget':
                    edits.append(['budget', rng.randrange(g),
                                  rng.choice([1, 10 ** 12]) if chaotic else rng.choice([10, 10 ** 12])])
                else:
                    edits.append(['cap', rng.randrange(n),
                                  rng.randint(0, 10 ** 9) if chaotic else rng.randint(4, 60)])
        if rng.random() < 0.1:
            edits.append(['weight', rng.randrange(d), 1]) if d else None
        if rng.random() < 0.08 and edits:
            edits.append(list(edits[rng.randrange(len(edits))]))
        txs.append({'revision': None, 'edits': edits, 'query': qmake()})
    if d == 0:
        txs = [tx for tx in txs if not any(e[0] in ('move', 'weight', 'class', 'bind', 'pin') for e in tx['edits'])]
    return {'topology': spec, 'caps': caps, 'groups': [[quota[i], budget[i]] for i in range(g)],
            'tasks': tasks, 'query': qmake(), 'transactions': txs}

def build_request(seed, sessions=2, force_bad=None, **kw):
    rng = random.Random(seed)
    out = []
    for _ in range(sessions):
        spec = rng.choice(TOPOS)
        out.append(build_session(rng, spec, force_bad=force_bad, **kw))
    return {'version': 2, 'sessions': out}

def adjust_revisions(request, response, match=0.9, rng=None):
    """Point most transaction revisions at the live counter using an oracle run."""
    rng = rng or random.Random(1234)
    if 'sessions' not in response:
        return request
    for sess, res in zip(request['sessions'], response['sessions']):
        prev = 0
        for tx, out in zip(sess['transactions'], res['transactions']):
            tx['revision'] = prev if rng.random() < match else rng.choice(
                [max(0, prev - 1), prev + 1, prev + 2, 10 ** 9, 0])
            prev = out['revision']
    return request

if __name__ == '__main__':
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    print(json.dumps(build_request(seed), separators=(',', ':')))
